#include "portfolio/application/candidates/capability_candidates.hpp"
#include <iostream>
using namespace axon::portfolio;
CapabilitySignature sig(std::string r,std::string i){CapabilitySignature x;x.stream={r,"stream"+r};x.signature_id=i;x.normalized_name="session revoke";x.bounded_context="identity";x.contracts={"RevokeRequest"};x.routes={"POST /revoke"};x.events={"session.revoked"};x.ast_fingerprints={"revoke"};return x;}
int main(){auto a=sig("one","a"),b=sig("two","b");auto id1=capability_reference_id(a),id2=capability_reference_id(b);CandidateGenerationConfig n;n.weights={{CandidateSignal::name,1}};CandidateGenerationConfig s;s.weights={{CandidateSignal::semantic,1}};auto promoted=[](const auto& c){return c.classification==CapabilityClassification::exact_duplicate||c.classification==CapabilityClassification::convergent_capability||c.classification==CapabilityClassification::shared_primitive_candidate;};auto run=[&](auto g,std::vector<SemanticCandidateHint> h){auto v=g.generate({a,b},h);return promoted(v.front())?1:0;};std::vector<SemanticCandidateHint> none,semantic={{id1,id2,.99}};std::cout<<"{\"schema_version\":\"axon/portfolio-eval/v1\",\"precision_at_1\":{\"name_only\":"<<run(CapabilityCandidateGenerator(n),none)<<",\"semantic_only\":"<<run(CapabilityCandidateGenerator(s),semantic)<<",\"multi_signal\":"<<run(CapabilityCandidateGenerator(),semantic)<<"},\"recall_at_1\":{\"name_only\":0,\"semantic_only\":0,\"multi_signal\":1}}\n";}
